import asyncio
import json
import logging
from datetime import datetime
from urllib.parse import urlparse
from urllib3.exceptions import MaxRetryError, NewConnectionError
from urllib3.util.retry import Retry
import aiohttp

logging.basicConfig(level=logging.INFO)

class URLFetcher:
    def __init__(self):
        self.session = aiohttp.ClientSession()
        self.retry = Retry(
            total=3,
            backoff_factor=1,
            status_forcelist=[500, 502, 503, 504]
        )
        self.session.mount("http://", aiohttp.ClientConnectorPool(maxsize=4))
        self.session.mount("https://", aiohttp.ClientConnectorPool(maxsize=4))

    async def fetch_url(self, url):
        try:
            async with self.session.get(url, retry=self.retry) as response:
                return {
                    "url": url,
                    "final_url": response.url,
                    "bytes": await response.content.read()
                }
        except (NewConnectionError, MaxRetryError, asyncio.TimeoutError) as e:
            return {
                "url": url,
                "error": str(e)
            }

async def process_urls(urls):
    fetcher = URLFetcher()
    tasks = []
    results = []
    log_entries = []

    for url in urls:
        task = asyncio.create_task(fetch_url(fetcher, url))
        tasks.append(task)

    for task in asyncio.as_completed(tasks):
        result = await task
        results.append(result)

    for result in results:
        log_entry = {
            "time": datetime.utcnow().isoformat() + "Z",
            "url": result["url"],
            "outcome": "error"
        }
        if "error" not in result:
            log_entry["outcome"] = "ok"
            log_entry["bytes"] = len(result["bytes"])
        else:
            log_entry["error"] = result["error"]
        log_entries.append(log_entry)

    return results, log_entries

async def fetch_url(fetcher, url):
    return await fetcher.fetch_url(url)

async def main():
    urls = []
    for line in sys.stdin:
        stripped = line.strip()
        if stripped:
            urls.append(stripped)

    if not urls:
        return

    results, log_entries = await process_urls(urls)

    async with aiohttp.ClientSession() as session:
        async with session.open("w", "run.log") as log_file:
            for entry in log_entries:
                log_file.write(json.dumps(entry) + "\n")

    for result in results:
        if "error" in result:
            print(json.dumps(result))
        else:
            print(json.dumps({
                "url": result["url"],
                "final_url": result["final_url"],
                "bytes": len(result["bytes"])
            }))

    if any("error" in result for result in results):
        exit(1)
    else:
        exit(0)

if __name__ == "__main__":
    import sys
    asyncio.run(main())

import asyncio
import json
import logging
import os
import sys
from datetime import datetime
from urllib.parse import urlparse
from urllib3.exceptions import MaxRetryError, RequestError
from urllib3.util.retry import Retry

logging.basicConfig(level=logging.INFO)

class URLFetcher:
    def __init__(self):
        self.semaphore = asyncio.Semaphore(4)
        self.results = []
        self.log_entries = []

    async def fetch_url(self, url):
        try:
            parsed = urlparse(url)
            if not parsed.scheme or not parsed.netloc:
                raise ValueError("Invalid URL")

            retry_strategy = Retry(
                total=3,
                backoff_factor=1,
                status_forcelist=[500, 502, 503, 504],
                allowed_methods=["HEAD", "GET"]
            )
            adapter = urllib3.PoolManager(
                retries=retry_strategy,
                maxsize=10,
                timeout=10.0
            )

            response = adapter.request(
                method="GET",
                url=url,
                preload_content=False
            )
            response.raise_for_status()

            content_length = int(response.headers.get('content-length', 0))
            final_url = response.url

            self.results.append({
                "url": url,
                "final_url": final_url,
                "bytes": content_length
            })

        except Exception as e:
            self.results.append({
                "url": url,
                "error": str(e)
            })

    async def process_urls(self, urls):
        tasks = []
        for url in urls:
            async with self.semaphore:
                task = asyncio.create_task(self.fetch_url(url))
                tasks.append(task)

        await asyncio.gather(*tasks)

    async def log_results(self):
        for i, result in enumerate(self.results):
            entry = {
                "time": datetime.utcnow().isoformat(timespec='seconds') + 'Z',
                "url": result["url"],
                "outcome": "ok" if "bytes" in result else "error"
            }
            if "bytes" in result:
                entry["bytes"] = result["bytes"]
            else:
                entry["error"] = result["error"]
            self.log_entries.append(entry)

    async def run(self, urls):
        await self.process_urls(urls)
        await self.log_results()

async def main():
    fetcher = URLFetcher()
    urls = []
    for line in sys.stdin:
        stripped = line.strip()
        if stripped:
            urls.append(stripped)

    if not urls:
        sys.exit(0)

    try:
        await fetcher.run(urls)
    except Exception as e:
        sys.exit(1)

    success = all(result.get("error") is None for result in fetcher.results)
    if not success:
        sys.exit(1)

    with open("run.log", "w") as log_file:
        for entry in fetcher.log_entries:
            log_file.write(json.dumps(entry) + "\n")

    with open("results.jsonl", "w") as out_file:
        for result in fetcher.results:
            if "error" in result:
                out_file.write(json.dumps({
                    "url": result["url"],
                    "error": result["error"]
                }) + "\n")
            else:
                out_file.write(json.dumps({
                    "url": result["url"],
                    "final_url": result["final_url"],
                    "bytes": result["bytes"]
                }) + "\n")

if __name__ == "__main__":
    import urllib3
    asyncio.run(main())
